head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.pMenuID = "STF05200";
scwin.fr_SecuGrpId = $c.lc.getSecuGrpId("STF05200");// mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.gMktTpCd = $c.session.getUserInfo("market");

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {

        // 초기화함수

        scwin.init();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출).
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {

    if (scwin.gIsurCd !== "" && scwin.gIsurCd !== undefined) {
        ibx_isurCd.setValue(scwin.gIsurCd);
        ibx_comNm.setValue(scwin.gComAbbrv);
        scwin.fr_SecuGrpId = scwin.gSecugrpId;

        scwin.vSPOT_ISU_TRD_MKT_TP_CD = scwin.gMktTpCd;
        $c.lc.gridNameChange(scwin.fr_SecuGrpId, "grd_IssRecv", "grd_histList");
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_COM_NM_onclick
 * @description 회사선택 목록 조회(팝업)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_COM_NM_onclick = async function() {
    try {
        let res = "";
        // 기업인수목적 회사와 주권 목록을 나눔 2010.05.30
        if (scwin.pMenuID === "STF05200") {
            res = await $c.lc.popFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
        }

        if(res) {
            ibx_isurCd.setValue(res.ISUR_CD);
            ibx_comNm.setValue(res.COM_NM);
            scwin.fr_SecuGrpId = res.SECUGRP_ID;
            scwin.vSPOT_ISU_TRD_MKT_TP_CD = res.SPOT_ISU_TRD_MKT_TP_CD;

            $c.lc.gridNameChange(scwin.fr_SecuGrpId, "grd_IssRecv", "grd_histList");

            scwin.issListSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name grd_IssRecv_oncelldblclick
 * @description 추가상장신청내역 , 상장 내역 더블클릭
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IssRecv_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        // let secugrpId = scwin.fr_SecuGrpId;
        scwin.clickBzProcsNo = ""; // 초기화

        scwin.gAcptNo = dlt_applyListRes.getCellData(rowIndex, "acptNo");
        scwin.gAcptNoListFee = scwin.gAcptNo;
        // gAcptNo = "20080616007146";
        scwin.gAcptSeq = dlt_applyListRes.getCellData(rowIndex, "byacptnoSeq");
        $c.lc.openDetailIssMng(ibx_isurCd, scwin.fr_SecuGrpId, scwin.gAcptNo);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.grd_IssRecv_oncelldblclick" });
    }
};

/**
 * @method
 * @name openDetailCorpIsu
 * @description 신규상장시 상장종목팝업창
 * @param {Number} rowIndex 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openDetailCorpIsu = async function(rowIndex) {
    try {
        scwin.gAcptNo = ""; // 초기화
        scwin.gAcptSeq = ""; // 초기화
        scwin.gAcptNoListFee = "";
        const secugrpId = scwin.fr_SecuGrpId;
        if (rowIndex > -1) {
            // 그리드에서 선택시
            scwin.setBzProcsNo(rowIndex);
        } else {
            // 신규버튼 선택시
            scwin.clickBzProcsNo = ""; // 초기화
        }
        await $c.lc.openDetailIssMng(ibx_isurCd, secugrpId, scwin.clickBzProcsNo);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.openDetailCorpIsu" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 함수명 : btn_Search_onclick() 설명 : btn_Search_onclick — 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    try {
        if (ibx_isurCd.getValue() === "") {
            $c.win.alert("[회사]를 선택하세요.");
            ibx_isurCd.focus();
            return;
        }

        scwin.issListSync();
        // dts_IssList.setRowPosition(dts_IssList.getTotalRow(), 0);
        // dts_IssRecv.setRowPosition(dts_IssRecv.getTotalRow(), 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 신규버튼 클릭 — 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (ibx_isurCd.getValue() === "") {
            $c.win.alert("[회사]를 선택하세요.");
            ibx_isurCd.focus();
            return;
        }

        await scwin.openDetailCorpIsu();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.btn_New_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description btn_Excel 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        scwin.excelDown();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name grd_IssRecv_OnDblClick
 * @description grd_IssRecv 더블클릭 — 선택 행 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IssRecv_OnDblClick = function(row, colid) {
    try {
        // TODO Stage2: 미정의 함수 scwin.fn_OpenDetailExtr — 원본에도 정의 없음(상세 팝업 열기), 대상 화면 확인 후 구현
        scwin.fn_OpenDetailExtr(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.grd_IssRecv_OnDblClick" });
    }
};

/**
 * @method
 * @name grd_IssList_OnDblClick
 * @description grd_IssList 더블클릭 — 선택 행 처리
 * @param {Number} row 행 인덱스
 * @param {String} colid 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_IssList_OnDblClick = function(row, colid) {
    try {
        // TODO Stage2: 외부 공통 $c.pre_newlisting 미반입 — 대응 함수 확인
        $c.pre_newlisting.fn_OpenDetailCorpIsu(row);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.grd_IssList_OnDblClick" });
    }
};

/**
 * @method
 * @name dts_IssList_OnLoadError
 * @description dts_IssList 로드 오류 콜백(레거시 Gauce 이벤트 — 현재 통신 오류 알림은 $c.sbm 공통이 담당)
 * @returns {void}
 * @hidden N
 */
scwin.dts_IssList_OnLoadError = function() {
    try {
        // var parentWin = frame.Provider("../frame_tail");
        // frame.Provider("../").frame_tail.vIsurCd;
        // $c.win.alert('[frame_tail.vIsurCd]'+frame.Provider("../").frame_tail.vIsurCd);
        $c.win.alert(dts_IssList);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.dts_IssList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IssRecv_OnLoadError
 * @description dts_IssRecv 로드 오류 콜백(레거시 Gauce 이벤트 — 현재 통신 오류 알림은 $c.sbm 공통이 담당)
 * @returns {void}
 * @hidden N
 */
scwin.dts_IssRecv_OnLoadError = function() {
    try {
        $c.win.alert(dts_IssRecv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.dts_IssRecv_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_IssRecv_OnLoadCompleted
 * @description dts_IssRecv 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_IssRecv_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_1.setValue("총 " + dts_IssRecv.getRowCount() + " 건");
        // dts_IssRecv.RowPosition = rowcount;
        // CloseWin(rowcount, grd_IsuRecv);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.dts_IssRecv_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_IssList_OnLoadCompleted
 * @description dts_IssList 로드 완료 후처리(레거시 Gauce 이벤트 — 순차 스타일에서는 await 뒤에서 호출)
 * @param {*} rowcount rowcount
 * @returns {void}
 * @hidden N
 */
scwin.dts_IssList_OnLoadCompleted = function(rowcount) {
    try {
        edt_TotalCnt_2.setValue("총 " + dts_IssList.getRowCount() + " 건");
        // dts_IssList.RowPosition = rowcount;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.dts_IssList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 버튼 클릭
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05200.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_excel1_onclick
 * @description 엑셀다운1 클릭 — 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_excel1_onclick = function (e) {
    try {
        if (grd_IssRecv.getRowCount() <= 0) {
            $c.win.alert("조회된 데이터가 없습니다.");
            return;
        }

        const gridId = grd_IssRecv;
        const infoArr = [];
        const options = {
            fileName : "추가상장신청내역.xlsx", // [default : excel.xlsx] options.fileName 값이 없을 경우 default값 세팅
            type : "2"
        };
        $c.data.downloadGridViewExcel(gridId,options,infoArr);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.btn_excel1_onclick" });
    }
};

/**
 * @method
 * @name btn_excel2_onclick
 * @description 엑셀다운2 클릭 — 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_excel2_onclick = function (e) {
    try {
        if (grd_histList.getRowCount() <= 0) {
            $c.win.alert("조회된 데이터가 없습니다.");
            return;
        }

        const gridId = grd_histList;
        const infoArr = [];
        const options = {
            fileName : "상장내역.xlsx", // [default : excel.xlsx] options.fileName 값이 없을 경우 default값 세팅
            type : "2"
        };
        $c.data.downloadGridViewExcel(gridId,options,infoArr);

    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05200.btn_excel2_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setBzProcsNo
 * @description 업무처리번호를 화면 상태값에 설정한다.
 * @param {Object} obj 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setBzProcsNo = async function(obj) {
    scwin.clickBzProcsNo = dlt_histListRes.getCellData(obj, "bzProcsNo");

    // 상장수수료로 인해 추가 TBLD_LIST_APPL_FORM 테이블에 접수번호가 없으면 SMS전송 버튼이 보이지 않음
    scwin.gAcptNoListFee = dlt_histListRes.getCellData(obj, "ACPT_NO");

    let reqMap = {
        // 종목코드
        acptNo: scwin.gAcptNoListFee
    };
    const sbmOptions = {
        id: "sbm_select_acptno",
        action: "/api/listing/lstproc/stock/chglisting/select-apfm-by-acptno",
        method: "get",
        target: "dma_IssListAcptNo=body",
        isProcessMsg: true
    };
    const res = await $c.sbm.executeDynamic(sbmOptions, reqMap);

    if (res.responseJSON.success) {
        scwin.gAcptNoListFee = dma_IssListAcptNo.get("acptNo");
    }
    // $c.win.alert("fn_setBzProcsNo():"+clickBzProcsNo);

};

/**
 * @method
 * @name issListSync
 * @description 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.issListSync = async function() {

    dma_searchReq.set("isurCd",ibx_isurCd.getValue());

    const sbmOptions = {
        id : "sbm_issuance",
        method: "get",
        ref: "dma_searchReq",
        action : "/api/listing/lstproc/stock/issuance/select-list",
        gridview: "grd_IssRecv|focus, grd_histList|focus",
        target : "dlt_applyListRes=body.applyList, dlt_histListRes=body.histList",
        isProcessMsg : true
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success) {
        edt_TotalCnt_1.setValue(res.responseJSON.body.applyList.length);
        edt_TotalCnt_2.setValue(res.responseJSON.body.histList.length);
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getBzProcsNo
 * @description 현재 업무처리번호를 반환한다.
 * @returns {*} 결과 값
 * @hidden N
 */
scwin.getBzProcsNo = function() {
    return scwin.clickBzProcsNo;
};

/**
 * @method
 * @name excelDown
 * @description 함수명 : fn_ExcelDown() 설명 : 정보를 excel로 다운 받는다
 * @returns {void}
 * @hidden N
 */
scwin.excelDown = function() {
    // 엑셀 로그
    $c.stf.doLogSave("ULDSTF05200", SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_IssList, {fileName: "주식발행내역", type: "8"});
};
